/// <summary>
/// The <c>AVABPJobsController</c> class is the controller class for <c>BP-Jobs</c>
/// </summary>
class AVABPJobsController extends SysOperationServiceController  implements BatchRetryable
{

}

Method.Source:
/// <summary>
///     AVA <c>new</c> method.
/// </summary>
protected void new()
{
    super();

    this.parmClassName(classStr(AVABPJobsService));
    this.parmMethodName(methodStr(AVABPJobsService, runService));
}

/// <summary>
/// N.Freidenberger 16.09.2025
/// </summary>
/// <returns>boolean</returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

/// <summary>
///     AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
/// <returns>
///     <c>AVABPJobsController</c> as return value
/// </returns>
public static AVABPJobsController newFromArgs(Args _args)
{
    AVABPJobsController controller;

    controller = new AVABPJobsController();
    controller.parmArgs(_args);
    // remove for activating value initialization of AVABPJobsContract.initialize()
    //controller.parmLoadFromSysLastValue(false);

    return controller;
}

/// <summary>
///     AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVABPJobsController     controller;
    AVABPJobsContract       dataContract;
    SysOperationStartResult sysOperationStartResult;

    Common                      locCommon;
    KCS_KBVBuildingProjectTable locKCS_KBVBuildingProjectTable;

    if (!_args)
    {
        throw error("@SYS25407");
    }

    controller  = AVABPJobsController::newFromArgs(_args);
    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);

    dataContract    = controller.getDataContractObject();
    if (_args && _args.record())
    {
        locCommon = _args.record();
        if(locCommon.RecId && locCommon.TableId == tableNum(KCS_KBVBuildingProjectTable))
        {
            locKCS_KBVBuildingProjectTable = locCommon;

            dataContract.parmArgs(_args);
            dataContract.parmKCS_KBVBuildingProjectID(locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
        }

    }
    dataContract.parmKCS_KBVBuildingProjectID(locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);

    sysOperationStartResult = controller.startOperation();

    if(sysOperationStartResult == SysOperationStartResult::Started)
    {
        info("@NDX:NXAOperationStarted");
    }
}

public static void newFromRico(Args  _args)
{
    AVABPJobsController     controller;
    AVABPJobsContract       dataContract;
    SysOperationStartResult sysOperationStartResult;

    Common                      locCommon;
    KCS_KBVBuildingProjectTable locKCS_KBVBuildingProjectTable;

    if (!_args)
    {
        throw error("@SYS25407");
    }

    controller  = AVABPJobsController::newFromArgs(_args);
    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);

    dataContract    = controller.getDataContractObject();
    if (_args && _args.record())
    {
        locCommon = _args.record();
        if(locCommon.RecId && locCommon.TableId == tableNum(KCS_KBVBuildingProjectTable))
        {
            locKCS_KBVBuildingProjectTable = locCommon;

            dataContract.parmArgs(_args);
            dataContract.parmKCS_KBVBuildingProjectID(locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
        }

    }
    dataContract.parmKCS_KBVBuildingProjectID(locKCS_KBVBuildingProjectTable.KCS_KBVBuildingProjectID);
    dataContract.parmRunFromRico(true);

    sysOperationStartResult = controller.startOperation();

    if(sysOperationStartResult == SysOperationStartResult::Started)
    {
        info("@NDX:NXAOperationStarted");
    }
}

/// <summary>
/// N.Freidenberger 12.09.2025
/// </summary>
/// <param name = "_dataContractFromBatchTask">_dataContractFromBatchTask</param>
/// <returns>AVABPJobsController</returns>
public static  AVABPJobsController      newFromBatchTask(AVABPJobsCalculationBatchTaskContract          _dataContractFromBatchTask)
{
    AVABPJobsController      controller = new AVABPJobsController();
    AVABPJobsContract        dataContract;
    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);
    dataContract = controller.getDataContractObject();

    dataContract.parmKCS_KBVBuildingProjectID(_dataContractFromBatchTask.parmKCS_KBVBuildingProjectID());
    dataContract.parmCreateActivities(_dataContractFromBatchTask.parmCreateActivities());
    dataContract.parmUpdateBPStatus(_dataContractFromBatchTask.parmUpdateBPStatus());
    dataContract.parmUpdateBPStatusGLB(_dataContractFromBatchTask.parmUpdateBPStatusGLB());
    dataContract.parmUpdateResponsibilities(_dataContractFromBatchTask.parmUpdateResponsibilities());
    dataContract.parmUpdateSalesVolume(_dataContractFromBatchTask.parmUpdateSalesVolume());
    dataContract.parmUpdateSalesVolumeGLB(_dataContractFromBatchTask.parmUpdateSalesVolumeGLB());
    dataContract.parmProcessingInterval(_dataContractFromBatchTask.parmProcessingInterval());
    dataContract.parmProcessSingleBatchtask(true);

    return controller;

}
